package com.dixitdada.journalApp.controller; import com.dixitdada.journalApp.dto.*; import com.dixitdada.journalApp.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/api/public") @RequiredArgsConstructor public class PublicController { private final UserService users; private final AuthenticationManager auth; private final CustomUserDetailsService uds; private final JwtService jwt; @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok");} @PostMapping("/register") public AuthResponse register(@Valid @RequestBody RegisterRequest r){users.register(r);UserDetails u=uds.loadUserByUsername(r.username());return new AuthResponse(jwt.generate(u),r.username());} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));UserDetails u=uds.loadUserByUsername(r.username());return new AuthResponse(jwt.generate(u),r.username());} }